{noformat}/*This validator modifies the value as well.*/export class VehicleUuidValidator implements ValidatorInterface<string> {
    public static readonly IS_INVALID = "Is invalid";
    public static readonly OUR_SCOOTER_QR_URL = "https://scooters.taxify.eu/qr/";

    public validate(value: string, params?: ValidateParams<any>): ValidatorResult {
        if (value === undefined) {
            return null;
        }

        // for case if our full url is passed        value = value.replace(VehicleUuidValidator.OUR_SCOOTER_QR_URL, "");

        // trim spaces        value = value.replace(" ", "");

        if (/^[0-9]{3}-[0-9]{3}$/.test(value) === true && params && params.obj) {
            params.obj[params.key] = value;
            return null;
        }

        if (/^[0-9]{6}$/.test(value) === true && params && params.obj) {
            params.obj[params.key] = value.substring(0, 3) + "-" + value.substring(3, 6);
            return null;
        }

        return {
            error: VehicleUuidValidator.IS_INVALID        };
    }
}{noformat}

